"use strict";
exports.major = function major(version) {
  return Number(version.split(".")[0]);
};
exports.isNewer = function isNewer(a, b) {
  const [x, y] = [a, b].map((v) => v.split(".").map(Number));
  for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] > y[i];
  return false;
};
exports.tag = function tag(prefix, version) {
  return prefix + version;
};
